import sys


def main():
    data = sys.stdin.read().split()
    n, l, r = int(data[0]), int(data[1]), int(data[2])
    a = list(map(int, data[3:3 + n]))
    count = 0
    for mask in range(1, 1 << n):
        s = 0
        for i in range(n):
            if mask >> i & 1:
                s += a[i]
        if l <= s <= r:
            count += 1
    print(count)


main()
